/**
 * tool-definitions — 4 уровня enforcement для CYCLE 4
 *
 * L1: tool.definition — напоминание в описании (prevention)
 * L2: tool.execute.before — маркер #CYCLE4_VERIFY в bash (enforcement)
 * L3: system.transform — STOP после 3+ вызовов без REFLECT (принуждение)
 * L4: session.compacting — REFLECT при переполнении контекста (автомат)
 *
 * + STALE триггер через event (каждые 50 tool success)
 */

import { type Plugin } from "@opencode-ai/plugin";
import * as fs from "fs";
import * as path from "path";

const HOME = process.env.HOME || "/home/kasiro";
const COUNTER_PATH = path.join(HOME, ".opencode", ".cycle-counter");
const STALE_COUNTER_PATH = path.join(HOME, ".opencode", ".stale-counter");
const STALE_TRIGGER_PATH = path.join(HOME, ".opencode", ".stale-trigger");
const STALE_THRESHOLD = 50;

display.text:
/**
 * tool-definitions — 4 уровня enforcement для CYCLE 4
 *
 * L1: tool.definition — напоминание в описании (prevention)
 * L2: tool.execute.before — маркер #CYCLE4_VERIFY в bash (enforcement)
 * L3: system.transform — STOP после 3+ вызовов без REFLECT (принуждение)
 * L4: session.compacting — REFLECT при переполнении контекста (автомат)
 *
 * + STALE триггер через event (каждые 50 tool success)
 */

import { type Plugin } from "@opencode-ai/plugin";
import * as fs from "fs";
import * as path from "path";

const HOME = process.env.HOME || "/home/kasiro";
const COUNTER_PATH = path.join(HOME, ".opencode", ".cycle-counter");
const STALE_COUNTER_PATH = path.join(HOME, ".opencode", ".stale-counter");
const STALE_TRIGGER_PATH = path.join(HOME, ".opencode", ".stale-trigger");
const STALE_THRESHOLD = 50;

interface CycleCounter {
  toolCalls: number;
  lastReflectCalls: number;
  lastReflectDate: string | null;
}

function readCounter(): CycleCounter {
  try {
    const data = fs.readFileSync(COUNTER_PATH, "utf-8");
    return JSON.parse(data);
  } catch {
    return { toolCalls: 0, lastReflectCalls: 0, lastReflectDate: null };
  }
}

function writeCounter(c: CycleCounter): void {
  try {
    fs.writeFileSync(COUNTER_PATH, JSON.stringify(c, null, 2), "utf-8");
  } catch {
    // Ошибка записи не критична
  }
}

export default (async () => {
  return {
    "tool.definition": async (input, output) => {
      const cycleNote =
        "\n\n\u26a0\ufe0f После использования (если задача ВЫПОЛНЕНА): VERIFY \u2192 CYCLE 4 LEARN.";

      if (output.description && !output.description.includes("CYCLE 4")) {
        output.description += cycleNote;
      }

      if (input.toolID === "bash") {
        const restrictions =
          "\n\nДОСТУПНЫЕ КОМАНДЫ:\n" +
          "  fd, rg, bun, bunx — быстрые аналоги find, grep, npm, npx\n" +
          "  ls, cat, echo, pwd, curl, mkdir, rm (осторожно), cp, mv, cd\n" +
          "  head, tail, wc, sort, uniq, tee, xargs, printf, test\n" +
          "  git, docker, doas, chmod, chown\n" +
          "  ps, df, du, free, uname, whoami, id, uptime\n" +
          "  python3, node, nvim\n\n" +
          "ЗАПРЕЩЕНЫ: find (\u2192 fd), grep (\u2192 rg), npm (\u2192 bun), npx (\u2192 bunx), glob (\u2192 fd)";

        output.description =
          "Execute shell commands in a restricted environment." +
          restrictions +
          cycleNote;
      }
    },

    "experimental.chat.system.transform": async (input, output) => {
      const counter = readCounter();
      const pendingToolCalls = counter.toolCalls - counter.lastReflectCalls;

      const warmRefresh =
        "[WARM REFRESH]\n" +
        "\u2705 CYCLE 1 на КАЖДОЕ сообщение\n" +
        "\u2705 VERIFY \u2192 CYCLE 4 LEARN\n" +
        "\u2705 CYCLE 4: task(general) — reflect+check+write одной задачей\n";

      let stopWarning = "";
      if (pendingToolCalls >= 3) {
        const lastReflectMsg = counter.lastReflectDate
          ? "Последний REFLECT: " + counter.lastReflectDate
          : "REFLECT не выполнялся в этой сессии";

        stopWarning =
          "\n\u26a0\ufe0f ПРИНУДИТЕЛЬНЫЙ STOP: " +
          pendingToolCalls +
          " tool call" +
          (pendingToolCalls % 10 === 1 ? "" : "ов") +
          " без CYCLE 4.\n" +
          lastReflectMsg +
          "\nНемедленно выполни CYCLE 4 LEARN: task(general, reflect+check+write)\n" +
          "После выполнения сбрось счётчик:\n" +
          "echo '{\"toolCalls\":0,\"lastReflectCalls\":0,\"lastReflectDate\":\"'$(date -u +%Y-%m-%dT%H:%M:%SZ)'\"}' > ~/.opencode/.cycle-counter\n";
      }

      const fullBlock = warmRefresh + stopWarning;

      if (output.system && Array.isArray(output.system)) {
        const header = "[WARM REFRESH]";
        const existingIdx = output.system.findIndex((s) =>
          s.startsWith(header)
        );

        if (existingIdx >= 0) {
          output.system[existingIdx] = fullBlock;
        } else {
          output.system.unshift(fullBlock);
        }
      }
    },

    "experimental.session.compacting": async (input, output) => {
      const isoNow = new Date().toISOString();

      output.prompt =
        "Сначала подведи итоги, потом сожми историю.\n\n" +
        "1. REFLECT: что сделано? какие решения приняты?\n" +
        "2. Что нового узнал? Где ошибся? Вывод?\n" +
        "3. Запиши уроки/решения (если нужно)\n" +
        "4. Сбрось счётчик CYCLE 4:\n" +
        "   echo '{\"toolCalls\":0,\"lastReflectCalls\":0,\"lastReflectDate\":\"" +
        isoNow +
        "\"}' > ~/.opencode/.cycle-counter\n" +
        "5. Сожми историю: сохрани архитектурные решения и ключевые результаты.\n" +
        "   Отбрось устаревшие tool output'ы.\n";

      output.context = [
        "Сохрани: архитектурные решения, несохранённые уроки, статус задач",
        "Отбрось: сырые output'ы команд, debug-логи, промежуточные результаты",
      ];
    },

    "tool.execute.before": async (input, output) => {
      if (input.tool === "bash" && output.args) {
        const cmd = output.args.command || "";
        if (
          typeof cmd === "string" &&
          cmd.length > 15 &&
          !cmd.startsWith("#")
        ) {
          output.args.command =
            "#CYCLE4_VERIFY: перед ответом проверь, завершена ли задача\n" +
            cmd;
        }
      }
    },

    "event": async (input) => {
      const event = input.event;
      if (!event || event.type !== "EventSessionNextToolSuccess") return;

      // Счётчик CYCLE 4
      const counter = readCounter();
      counter.toolCalls++;
      writeCounter(counter);

      // STALE триггер (каждые 50 tool success)
      let staleCount = 0;
      try {
        const data = fs.readFileSync(STALE_COUNTER_PATH, "utf-8").trim();
        staleCount = parseInt(data, 10) || 0;
      } catch {}

      staleCount++;
      if (staleCount >= STALE_THRESHOLD) {
        try {
          fs.writeFileSync(STALE_TRIGGER_PATH, new Date().toISOString(), "utf-8");
          fs.writeFileSync(STALE_COUNTER_PATH, "0", "utf-8");
        } catch {}
      } else {
        try {
          fs.writeFileSync(STALE_COUNTER_PATH, String(staleCount), "utf-8");
        } catch {}
      }
    },
  };
}) satisfies Plugin;

